92	const DEDUCTIBLE_PER_DAMAGE = 100;
93	const HALVED_ENCHANTMENT_THRESHOLD = 8;
94	const HALVED_REIMBURSEMENT = 0.5;
95	const FULL_REIMBURSEMENT = 1;
96	const CAP_MULTIPLIER = 2;
97	
98	const ALIKE_BLOCK_SIZE = 3;
99	const ALIKE_BLOCK_PREMIUM = 60;
100	
101	const sum = (amounts: number[]): number =>
102	  amounts.reduce((total, amount) => total + amount, 0);
103	
104	type AlikeGroup = [type: string, count: number];
105	
106	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
107	  const countByType = new Map<string, number>();
108	
109	  for (const item of items) {
110	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
111	  }
112	
113	  return [...countByType];
114	};
115	
116	/**
117	 * The MHPCO refusing to process a scenario. Every rejection in this module ends
118	 * here, so "rejected" is one word with one meaning rather than a `throw` open-
119	 * coded at each site.
120	 *
121	 * Returns `never`, which is what lets it be used as an EXPRESSION — the arm of a
122	 * conditional, the fallback of a `??` — instead of forcing every guard into a
123	 * statement block. The rejections then read alike whatever their shape.
124	 */
125	const reject = (message: string): never => {
126	  throw new Error(message);
127	};
128	
129	/**
130	 * Rejection for a value the MHPCO requires but does not have. The two rate
131	 * tables are keyed by item type, and an item type absent from either has no
132	 * answer to give — so the lookup rejects rather than handing back `undefined`
133	 * for the arithmetic downstream to turn into NaN.
134	 *
135	 * Deliberately narrow: this covers a MISSING value only. A value that is
136	 * present but unacceptable — a damage amount of -200, say — is a different
137	 * shape of rejection: it has a value to name in its message, so it states its
138	 * own condition and calls `reject` directly rather than being forced through
139	 * the `undefined` check here.
140	 */
141	const required = <T>(value: T | undefined, message: string): T =>
142	  value ?? reject(message);
143	
144	const uninsuredTypeMessage = (type: string): string =>
145	  `The MHPCO does not insure items of type "${type}".`;
146	
147	/**
148	 * A damage entry reports what an incident COST, and a cost below zero is not a
149	 * smaller claim — it is a claim that would pay the MHPCO. Nothing downstream
150	 * treats it as a rejection on its own: the deductible subtraction would quietly
151	 * turn -200 G of "damage" into a -300 G contribution to the claim total, netting
152	 * off against the genuine damages beside it. So the entry is refused at the door.
153	 */
154	const isNegative = (amount: number): boolean => amount < 0;
155	
156	const negativeAmountMessage = (amount: number): string =>
157	  `A damage amount cannot be negative, but the claim reports ${amount} G.`;
158	
159	const priceListEntryOf = (type: string): PriceListEntry =>
160	  required(PRICE_LIST[type], uninsuredTypeMessage(type));
161	
162	const basePremiumOfType = (type: string): number =>
163	  priceListEntryOf(type).basePremium;
164	
165	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
166	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
167	
168	  return count * basePremiumOfType(type);
169	};
170	
171	/**
172	 * The policy base premium: the sum of the item base premiums, with the
173	 * alike-block discount applied. Policy-scope modifiers are percentages OF
174	 * THIS amount — never of a total that already includes item surcharges.
175	 */
176	const policyBasePremiumOf = (items: Item[]): number =>
177	  sum(groupAlikeItems(items).map(basePremiumOfGroup));
178	
179	/**
180	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
181	 * premium, independent of the policy base and of the alike-block discount.
182	 */
183	const isCursed = (item: Item): boolean => item.cursed === true;
184	
185	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
186	
187	const carriesEnchantmentSurcharge = (item: Item): boolean =>
188	  enchantmentOf(item) >= SURCHARGED_ENCHANTMENT_THRESHOLD;
189	
190	const itemSurchargeRateOf = (item: Item): number =>
191	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
192	  (carriesEnchantmentSurcharge(item) ? ENCHANTMENT_SURCHARGE : 0);
193	
194	const itemSurchargesOf = (items: Item[]): number =>
195	  items.reduce(
196	    (total, item) =>
197	      total + basePremiumOfType(item.type) * itemSurchargeRateOf(item),
198	    0,
199	  );
200	
201	/**
202	 * Policy-scope modifiers: each is a percentage of the policy base premium.
203	 * Surcharges and discounts are netted into a single rate, so the policy base is
204	 * multiplied exactly once — this keeps the result free of the rounding drift
205	 * that separate discount and surcharge terms would introduce. The netted rate
206	 * (and hence the returned amount) is negative when the discounts outweigh the
207	 * surcharges.
208	 */
209	const isLongStanding = (customer: Customer): boolean =>
210	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
211	
212	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
213	  FIRST_INSURANCE_SURCHARGE -
214	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
215	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
216	
217	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
218	  policyBase * policyModifierRateOf(policy);
219	
220	const quotePremium = (items: Item[], policy: Policy): number => {
221	  const policyBase = policyBasePremiumOf(items);
222	  const premium =
223	    policyBase +
224	    itemSurchargesOf(items) +
225	    policyModifiersOn(policyBase, policy) +
226	    PROCESSING_FEE;
227	
228	  return roundedInFavourOfMHPCO.collected(premium);
229	};
230	
231	/**
232	 * Whether any step precedes this one. A quote is a follow-up contract when the
233	 * customer already holds one, and today every step is a quote — so "has a
234	 * predecessor" and "is a follow-up contract" coincide.
235	 *
236	 * They stop coinciding once claim steps exist: a claim at index 0 would make
237	 * the quote at index 1 look like a follow-up. At that point the caller must
238	 * count preceding QUOTE steps instead of asking this. The name is deliberately
239	 * about position, not contracts, so that the substitution is a visible change
240	 * at the call site rather than a silent redefinition here.
241	 */
242	const hasPrecedingStep = (stepIndex: number): boolean => stepIndex > 0;
243	
244	const insuredValueOfType = (type: string): number =>
245	  priceListEntryOf(type).insuranceValue;
246	
247	const insuranceSumOf = (items: Item[]): number =>
248	  sum(items.map(({ type }) => insuredValueOfType(type)));
249	
250	const isReimbursedByHalf = (item: Item): boolean =>
251	  enchantmentOf(item) >= HALVED_ENCHANTMENT_THRESHOLD;
252	
253	/**
254	 * The share of a damage amount that is reimbursed, before the deductible.
255	 *
256	 * The specification's dragon-material rule ("damage to items made of dragon
257	 * material is fully reimbursed") is deliberately ABSENT here, and `Item` has no
258	 * `material` field. The rule is unobservable given the other rules:
259	 *
260	 * - Full reimbursement is already FULL_REIMBURSEMENT, the default rate, so on
261	 *   items below the halving threshold a dragon clause would compute what this
262	 *   function computes anyway.
263	 * - The only inputs where the two clauses disagree are items with enchantment
264	 *   >= HALVED_ENCHANTMENT_THRESHOLD, and there the spec awards the conflict to
265	 *   halving ("both clauses apply; the 50 % rule wins").
266	 *
267	 * So no input distinguishes an implemented dragon clause from this one. The
268	 * spec's own examples confirm it: a steel sword and a dragon sword at
269	 * enchantment 9 with 1000 G damage both pay out 400 G. Implementing it would
270	 * add an unreachable branch and a field nothing reads.
271	 *
272	 * This stops holding the moment dragon material gains an effect OUTSIDE the
273	 * reimbursement rate — a different deductible, or an exemption from the payout
274	 * cap. Such a rule would need a real `material` field and a real branch.
275	 */
276	const reimbursementRateFor = (item: Item): number =>
277	  isReimbursedByHalf(item) ? HALVED_REIMBURSEMENT : FULL_REIMBURSEMENT;
278	
279	/**
280	 * The insured item a damage entry refers to. A damage entry can fail to name one
281	 * for two DIFFERENT reasons, and they get different messages because they are
282	 * different problems for the claimant:
283	 *
284	 * - The MHPCO does not insure the type at all (a broomstick). Nothing the
285	 *   claimant does to their policy would help.
286	 * - The type is insurable but is not on THIS policy (an amulet, on a policy
287	 *   covering only a sword). Perfectly insurable — just not insured here.
288	 *
289	 * The first is checked first, because it is the broader fact: an uninsurable
290	 * type is also, trivially, not on the policy, and reporting it as a coverage gap
291	 * would send the claimant off to read a policy that was never the problem.
292	 */
293	const isInsurableType = (type: string): boolean => type in PRICE_LIST;
294	
295	const insuredItemFor = ({ itemType }: Damage, items: Item[]): Item => {
296	  if (!isInsurableType(itemType)) reject(uninsuredTypeMessage(itemType));
297	
298	  return required(
299	    items.find(({ type }) => type === itemType),
300	    `The policy does not cover an item of type "${itemType}".`,
301	  );
302	};
303	
304	/**
305	 * A single damage entry settles in two stages, in this order: the reimbursement
306	 * rate applies to the damage amount, and the deductible comes off the result.
307	 * The spec is explicit that the sequencing matters ("the 50 % rule wins, then
308	 * deductible"), so it is spelled out rather than left to operator precedence.
309	 */
310	const payoutForDamage = (damage: Damage, items: Item[]): number => {
311	  if (isNegative(damage.amount)) reject(negativeAmountMessage(damage.amount));
312	
313	  const reimbursed =
314	    damage.amount * reimbursementRateFor(insuredItemFor(damage, items));
315	
316	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
317	};
318	
319	/**
320	 * The quote step a claim is filed against. This ASSUMES the referenced index
321	 * holds a quote, and the assumption is unchecked: a claim naming a claim step —
322	 * or an out-of-range index — fails downstream with an opaque undefined-property
323	 * error instead of a rejection.
324	 *
325	 * NO test forces the check, and none is pending: every claim in the suite
326	 * references `policy: 0`, which is always a quote. The two remaining rejection
327	 * tests are both about the CONTENTS of a claim (an unknown item type, a
328	 * negative amount) and are served elsewhere — the item-type one by
329	 * `insuredItemFor`, which already rejects.
330	 *
331	 * So the cast stays, deliberately: writing the guard now would be implementing
332	 * ahead of the tests. It is isolated here so that the day a scenario can point
333	 * a claim at a non-quote step, this is the one function that has to change.
334	 */
335	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep =>
336	  steps[claim.policy] as QuoteStep;
337	
338	/**
339	 * A damage entry names a TYPE, not a particular item, so two entries reading
340	 * `sword` are two separate swords damaged — each with its own deductible. A
341	 * policy covering one sword therefore cannot answer a claim for two of them.
342	 *
343	 * This is why the check lives at claim scope: `insuredItemFor` resolves each
344	 * entry on its own and would happily match both entries to the same insured
345	 * sword. Only here are all the entries visible at once.
346	 */
347	const damagedCountByType = (incident: Incident): Map<string, number> => {
348	  const counts = new Map<string, number>();
349	
350	  for (const { itemType } of incident.damages) {
351	    counts.set(itemType, (counts.get(itemType) ?? 0) + 1);
352	  }
353	
354	  return counts;
355	};
356	
357	const rejectOverclaimedTypes = (incident: Incident, items: Item[]): void => {
358	  const insuredCounts = new Map(groupAlikeItems(items));
359	
360	  for (const [itemType, damaged] of damagedCountByType(incident)) {
361	    const insured = insuredCounts.get(itemType) ?? 0;
362	
363	    if (damaged > insured) {
364	      reject(
365	        `The claim reports ${damaged} damaged items of type "${itemType}", but the policy covers ${insured}.`,
366	      );
367	    }
368	  }
369	};
370	
371	/**
372	 * The total a claim asks for: every damage entry settled on its own, then
373	 * summed. Unclamped — the payout cap is applied to this total, not per damage.
374	 */
375	const amountClaimed = (incident: Incident, items: Item[]): number => {
376	  rejectOverclaimedTypes(incident, items);
377	
378	  return incident.damages.reduce(
379	    (total, damage) => total + payoutForDamage(damage, items),
380	    0,
381	  );
382	};
383	
384	/**
385	 * Applying the payout cap to a claim: a policy pays at most what is left of its
386	 * cap, and whatever it pays comes off that remainder. Pure, and stated as a
387	 * before/after pair, so the invariant `payout + capAfter === capBefore` is
388	 * visible in one place rather than spread across the caller.
389	 */
390	const chargedAgainstCap = (claimed: number, capBefore: number): ClaimResult => {
391	  const payout = Math.min(claimed, capBefore);
392	
393	  return { payout, remainingCap: capBefore - payout };
394	};
395	
396	/**
397	 * The cap a policy starts with, before any claim has drawn on it.
398	 */
399	const initialCapOf = (policy: QuoteStep): number =>
400	  CAP_MULTIPLIER * insuranceSumOf(policy.items);
401	
402	/**
403	 * Settling a claim DRAWS DOWN the policy's remaining cap: the result depends on
404	 * how much earlier claims already consumed, so the running cap is read from and
405	 * written back to `capRemainingByPolicy`. That state write is this function's
406	 * one effect, and it is deliberately the last statement.
407	 */
408	const settleClaim = (
409	  claim: ClaimStep,
410	  steps: Step[],
411	  capRemainingByPolicy: Map<number, number>,
412	): ClaimResult => {
413	  const policy = policyReferencedBy(claim, steps);
414	  const capBefore =
415	    capRemainingByPolicy.get(claim.policy) ?? initialCapOf(policy);
416	  const settled = chargedAgainstCap(
417	    roundedInFavourOfMHPCO.disbursed(
418	      amountClaimed(claim.incident, policy.items),
419	    ),
420	    capBefore,
421	  );
422	
423	  capRemainingByPolicy.set(claim.policy, settled.remainingCap);
424	
425	  return settled;
426	};
427	
428	const priceQuote = (
429	  quote: QuoteStep,
430	  stepIndex: number,
431	  customer: Customer,
432	): QuoteResult => ({
433	  premium: quotePremium(quote.items, {
434	    customer,
435	    isFollowUpContract: hasPrecedingStep(stepIndex),
436	  }),
437	});
438	
439	/**
440	 * Steps are settled IN ORDER, and that order is load-bearing: a claim's payout
441	 * depends on how much of the policy's cap the claims before it consumed.
442	 */
443	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
444	  const capRemainingByPolicy = new Map<number, number>();
445	
446	  return {
447	    results: scenario.steps.map((step, stepIndex) =>
448	      isQuoteStep(step)
449	        ? priceQuote(step, stepIndex, scenario.customer)
450	        : settleClaim(step, scenario.steps, capRemainingByPolicy),
451	    ),
452	  };
453	};
